export type CriterionState = 'draft' | 'active' | 'ended' | 'replaced';

export type PlanningCriterion = {
    id: PlanningCriterionId;
    userId: UserId;
    policy: CriterionPolicy;
    sourceSprintId: SprintId;
    state: CriterionState;
    replacedBy?: PlanningCriterionId;
    createdAt: Instant;
};

export type CriterionResult = {
    tasks: Array<TaskFact>;
    done: Array<TaskFact>;
    carriedOver: Array<TaskFact>;
    planned: PlanningTotal;
    actualHours: number;
};

export type RetroCriterion = {
    criterion: PlanningCriterion;
    view: CriterionView;
    areaName?: string;
};

/**
 * `decisionMissing`: 続ける / 終える / 置き換える is not chosen (invariant 36). `continueWithDraft`: 続ける keeps the active criterion, so the draft must go (invariant 35).
 */
export type RetroBlocker = 'decisionMissing' | 'continueWithDraft';

export type ActualTarget = {
    sprintTaskId: SprintTaskId;
    occurrenceId?: OccurrenceId;
    date: LocalDate;
};

export type RetroOccurrence = {
    occurrence: Occurrence;
    title: string;
    actualHours: number;
    target: ActualTarget;
};

export type CarryOverPlaces = {
    total: number;
    inNext: number;
    candidates: number;
    completed: number;
    archived: number;
};

export type CarryOverPlace = 'inNext' | 'candidate' | 'completed' | 'archived';

export type CarryOverTask = {
    taskId: TaskId;
    place: CarryOverPlace;
};

export type RetroData = {
    sprint: Sprint;
    number: number;
    week?: SprintWeek;
    today: LocalDate;
    timeZone: TimeZone;
    facts: RetroFacts;
    /**
     * Every Area by ID, as this Sprint shows it (F5).
     */
    sprintAreas: {
        [key: string]: SprintAreaLabel;
    };
    areas: Array<SprintAreaLabel>;
    /**
     * The titles of the Tasks the previews and carry-over name, by Task ID.
     */
    taskTitles: {
        [key: string]: string;
    };
    /**
     * The criterion this Sprint had, what it did, and the decision.
     */
    used?: {
        criterion: PlanningCriterion;
        view: CriterionView;
        areaName?: string;
        appliedAtConfirm: boolean;
        result: CriterionResult;
        decision?: RetroDecision;
    };
    draft?: RetroCriterion;
    pins: Array<RetroPin>;
    reflection: string;
    improvement?: string;
    blockers: Array<RetroBlocker>;
    /**
     * Actual hours added in Review go to this day (F22).
     */
    actualDate: LocalDate;
    occurrences: Array<RetroOccurrence>;
    carryOver: CarryOverPlaces;
    carryOverTasks: Array<CarryOverTask>;
};

